def is_substring_of_repeated_yes(s):
    repeated_yes = "Yes" * 50  # A sufficiently long string of "Yes" repeated
    return s in repeated_yes

def main():
    t = int(input())
    results = []
    for _ in range(t):
        s = input()
        results.append("YES" if is_substring_of_repeated_yes(s) else "NO")
    for result in results:
        print(result)

main()
